mapper.select:
{CALL sp_discharge_settlement(
    #{admissionId, mode=IN, jdbcType=BIGINT},
    #{operatorId, mode=IN, jdbcType=BIGINT},
    #{settlementId, mode=OUT, jdbcType=BIGINT}
)}

SELECT aa.*, a.admission_no, p.patient_no, p.name patient_name, d.name department_name
FROM account_alert aa JOIN admission a ON a.id=aa.admission_id
JOIN patient p ON p.id=a.patient_id JOIN department d ON d.id=a.department_id

    aa.status=#{status}
    AND aa.level=#{level}

ORDER BY FIELD(aa.level,'CRITICAL','WARNING','INFO'), aa.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM account_alert aa

    aa.status=#{status}
    AND aa.level=#{level}
